// Generate additional projects programmatically to reach 60 total
const additionalProjects = [];
const baseImages = [
  'https://images.unsplash.com/photo-1564013799919-ab600027ffc6',
  'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9',
  'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c',
  'https://images.unsplash.com/photo-1628744449002-f7a527501b76',
  'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d',
  'https://images.unsplash.com/photo-1600607687644-c7171b42498b',
  'https://images.unsplash.com/photo-1556909114-f6e7ad7d3136',
  'https://images.unsplash.com/photo-1600566753376-12c8ab7fb75b'
];

const projectTypes = ['Architecture', 'Interior', 'Landscape', 'Urban Planning', 'Renovation'];
const locations = ['New York, USA', 'London, UK', 'Tokyo, Japan', 'Paris, France', 'Sydney, Australia', 'Dubai, UAE', 'Barcelona, Spain', 'Copenhagen, Denmark'];
const sizes = ['small', 'medium', 'large'];

for (let i = 11; i <= 60; i++) {
  const baseImageIndex = (i - 11) % baseImages.length;
  const baseImageUrl = baseImages[baseImageIndex];
  const projectType = projectTypes[(i - 11) % projectTypes.length];
  const location = locations[(i - 11) % locations.length];
  const size = sizes[(i - 11) % sizes.length];
  
  additionalProjects.push({
    id: i,
    title: `Project ${i}`,
    location: location,
    year: "2023",
    area: `${150 + (i * 10)} sqm`,
    category: projectType,
    type: 'Contemporary',
    description: `A stunning ${projectType.toLowerCase()} project featuring modern design principles and innovative solutions.`,
    image: `${baseImageUrl}?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&h=400&q=80`,
    exteriorImages: [
      { mainImage: `${baseImageUrl}?ixlib=rb-4.0.3&auto=format&fit=crop&w=360&h=543&q=80`, hoverImage: `${baseImages[(baseImageIndex + 1) % baseImages.length]}?ixlib=rb-4.0.3&auto=format&fit=crop&w=360&h=543&q=80` }
    ],
    interiorImages: [
      { mainImage: `${baseImages[(baseImageIndex + 2) % baseImages.length]}?ixlib=rb-4.0.3&auto=format&fit=crop&w=360&h=543&q=80`, hoverImage: `${baseImages[(baseImageIndex + 3) % baseImages.length]}?ixlib=rb-4.0.3&auto=format&fit=crop&w=360&h=543&q=80` }
    ],
    mainImage: `${baseImageUrl}?ixlib=rb-4.0.3&auto=format&fit=crop&w=360&h=543&q=80`,
    hoverImage: `${baseImageUrl}?ixlib=rb-4.0.3&auto=format&fit=crop&w=360&h=543&q=80`,
    projectCategory: (i % 2 === 0) ? "EXTERIOR" : "INTERIOR",
    size: size
  });
}

// Combine original projects with additional projects
export const allProjects = [...projects, ...additionalProjects];

